# Clean-room PHP language-pack rules. Each pattern is intentionally limited to a single,
# reviewable source-line shape; rules that require data flow remain outside this pack.
CC = "commentOnlyLine"

SOURCES = {
    "bugs": "https://www.php.net/manual/en/language.operators.comparison.php",
    "err": "https://www.php.net/manual/en/language.exceptions.php",
    "res": "https://www.php.net/manual/en/language.oop5.decon.php",
    "inj": "https://owasp.org/www-community/attacks/SQL_Injection",
    "crypto": "https://www.php.net/manual/en/book.password.php",
    "authz": "https://owasp.org/www-project-top-ten/",
    "hotspot": "https://www.php.net/manual/en/security.php",
    "api": "https://www.php.net/manual/en/funcref.php",
    "types": "https://www.php.net/manual/en/language.types.declarations.php",
    "perf": "https://www.php.net/manual/en/language.generators.overview.php",
    "maint": "https://www.php-fig.org/psr/psr-12/",
}

DEFAULTS = {
    "bugs": ("bug", "rel", "medium", "CWE-682"),
    "err": ("smell", "maint", "medium", ""),
    "res": ("smell", "maint", "medium", "CWE-404"),
    "inj": ("vuln", "sec", "high", "CWE-74"),
    "crypto": ("hotspot", "sec", "high", "CWE-327"),
    "authz": ("hotspot", "sec", "high", "CWE-862"),
    "hotspot": ("hotspot", "sec", "medium", "CWE-489"),
    "api": ("smell", "maint", "low", ""),
    "types": ("smell", "maint", "medium", ""),
    "perf": ("smell", "maint", "low", ""),
    "maint": ("smell", "maint", "low", ""),
}

RATIONALES = {
    "bugs": "This construct can yield a surprising result or fail independently of the surrounding business logic.",
    "err": "This error-handling form loses information or obscures the program's recovery behavior.",
    "res": "This resource-ownership form makes prompt and deterministic cleanup easy to omit.",
    "inj": "This line crosses an interpreter or I/O boundary with dynamic data and needs a structured alternative.",
    "crypto": "This security-sensitive primitive or parameter requires review against the intended protection goal.",
    "authz": "This authorization boundary needs an explicit least-privilege decision.",
    "hotspot": "This line changes a security-sensitive runtime behavior and requires deliberate review.",
    "api": "This API has a clearer or safer PHP alternative for ordinary application code.",
    "types": "This form weakens PHP's useful type guarantees or defers a mismatch until runtime.",
    "perf": "This form performs avoidable work or allocation for a common PHP operation.",
    "maint": "This syntax increases reading or maintenance cost without conveying additional intent.",
}

REMEDIATIONS = {
    "bugs": "Use the explicit, checked PHP form demonstrated by the compliant example.",
    "err": "Preserve the throwable or make the failure path explicit.",
    "res": "Close or release the resource through a bounded owner on every path.",
    "inj": "Use a structured API for the sink, validate untrusted values, and apply context-appropriate encoding or binding.",
    "crypto": "Use a current password or cryptographic API with reviewed parameters.",
    "authz": "Check the authenticated actor's required role, capability, tenant, or ownership before acting.",
    "hotspot": "Restrict the behavior or document and review the boundary before enabling it.",
    "api": "Use the modern PHP API shown in the compliant example.",
    "types": "Declare and preserve the narrowest useful type at this boundary.",
    "perf": "Use the direct operation shown in the compliant example.",
    "maint": "Prefer the simpler, explicit PHP form shown in the compliant example.",
}


def r(fam, ident, title, regex, nc, c, *, cwe=None, source=None, remediation=None, type=None, qual=None, sev=None):
    dt, dq, ds, dc = DEFAULTS[fam]
    weakness = dc if cwe is None else cwe
    concept_source = source or ("https://cwe.mitre.org/data/definitions/" + weakness[4:] + ".html" if weakness else SOURCES[fam])
    return {
        "id": "php:" + ident, "lang": "php", "type": type or dt, "qual": qual or dq,
        "sev": sev or ds, "cwe": weakness, "owasp": "",
        "tags": ["sast", "php", fam], "effort": 15, "title": title,
        "desc": "Detects " + title.lower() + " in PHP source.",
        "cat_desc": "Detects " + title.lower() + " in PHP source.",
        "rationale": RATIONALES[fam], "remediation": remediation or REMEDIATIONS[fam],
        "source": concept_source, "re": regex, "nc": nc, "c": c, "skip": CC,
        "detection": "pattern",
    }


