    r("api", "each-usage", "Removed each API", r"\beach\s*\(", 'while (each($items)) work();', 'foreach ($items as $item) work();'),
    r("api", "create-function", "Removed create_function API", r"\bcreate_function\s*\(", '$fn = create_function("$x", "return $x;");', '$fn = static fn ($x) => $x;'),
    r("api", "utf8-encode", "Deprecated utf8_encode API", r"\butf8_encode\s*\(", '$text = utf8_encode($text);', '$text = mb_convert_encoding($text, "UTF-8", "ISO-8859-1");'),
    r("api", "utf8-decode", "Deprecated utf8_decode API", r"\butf8_decode\s*\(", '$text = utf8_decode($text);', '$text = mb_convert_encoding($text, "ISO-8859-1", "UTF-8");'),
    r("api", "money-format", "Removed money_format API", r"\bmoney_format\s*\(", '$price = money_format("%i", $amount);', '$price = number_format($amount, 2);'),
