    # perf (8)
    r("perf", "count-in-loop", "count evaluated in loop condition", r"for\s*\([^;]*;\s*[^;]*count\s*\(", 'for ($i = 0; $i < count($items); $i++) work();', '$count = count($items); for ($i = 0; $i < $count; $i++) work();'),
