    r("perf", "array-keys-in-loop", "array_keys allocated in loop", r"\b(for|foreach|while)\b[^\n]*array_keys\s*\(", 'foreach ($rows as $row) { array_keys($row); }', '$keys = array_keys($rows[0]);'),
    r("perf", "sort-for-first", "Full sort used to select first value", r"\bsort\s*\(\s*\$[A-Za-z_]\w*\s*\)", 'sort($scores); $best = $scores[0];', '$best = min($scores);'),

    # maint (21)
    r("maint", "short-open-tag", "Short PHP opening tag", r"^\s*<\?\s+", '<? echo $name; ?>', '<?php echo $name; ?>'),
    r("maint", "closing-tag", "Closing PHP tag in source-only file", r"\?>\s*$", '<?php echo $name; ?>', '<?php final class User {}'),
    r("maint", "var-property", "Legacy var property declaration", r"\bvar\s+\$", 'var $name;', 'private string $name;'),
    r("maint", "else-if-spacing", "Non-idiomatic else if spelling", r"\belse\s+if\s*\(", 'else if ($ready) work();', 'elseif ($ready) work();'),
    r("maint", "array-long-syntax", "Long array syntax", r"\barray\s*\(", '$items = array(1, 2);', '$items = [1, 2];'),
    r("maint", "array-push-single", "array_push used for one item", r"array_push\s*\(\s*\$[A-Za-z_]\w*\s*,\s*[^,\)]+\)", 'array_push($items, $item);', '$items[] = $item;'),
    r("maint", "boolean-literal-comparison", "Boolean compared to literal", r"={2,3}\s*(true|false)\b", 'if ($enabled === true) work();', 'if ($enabled) work();'),
    r("maint", "empty-array-comparison", "Array compared to empty literal", r"\$[A-Za-z_]\w*\s*={2,3}\s*\[\s*\]", 'if ($items === []) work();', 'if (!$items) work();'),
    r("maint", "nested-ternary", "Nested ternary expression", r"\?[^;\n]*\?[^;\n]*:", '$label = $a ? $b ? "x" : "y" : "z";', '$label = match (true) { $a && $b => "x", default => "z" };'),
    r("maint", "ternary-true", "Ternary returning true", r"\?\s*true\s*:\s*false", '$ok = $ready ? true : false;', '$ok = $ready;'),
    r("maint", "ternary-false", "Ternary returning false", r"\?\s*false\s*:\s*true", '$ok = $ready ? false : true;', '$ok = !$ready;'),
    r("maint", "unnecessary-else-return", "Else after return", r"if\s*\([^)]*\)\s*\{[^}]*return[^}]*\}\s*else", 'if ($bad) { return; } else { work(); }', 'if ($bad) { return; } work();'),
    r("maint", "empty-method", "Empty method body", r"function\s+\w+\s*\([^)]*\)\s*\{\s*\}", 'function refresh() {}', 'function refresh(): void { $this->repo->refresh(); }'),
    r("maint", "empty-class", "Empty class body", r"class\s+\w+[^\{]*\{\s*\}", 'class Empty {}', 'class User { public function name(): string { return "x"; } }'),
    r("maint", "magic-number", "Unexplained large numeric literal", r"\b([2-9][0-9]{2,}|1[0-9]{3,})\b", 'if ($seconds > 86400) expire();', 'if ($seconds > SECONDS_PER_DAY) expire();'),
    r("maint", "too-many-parameters", "Function with many parameters", r"function\s+\w+\s*\([^)]*,[^)]*,[^)]*,[^)]*,[^)]*,[^)]*,[^)]*,", 'function connect($a,$b,$c,$d,$e,$f,$g,$h) {}', 'function connect(ConnectionOptions $options): void {}'),
    r("maint", "single-letter-variable", "Single-letter variable name", r"\$[a-z]\s*=", '$x = loadUser();', '$user = loadUser();'),
    r("maint", "global-keyword", "Global state import", r"\bglobal\s+\$", 'global $config;', '$config = $this->config;'),
    r("maint", "goto-usage", "Goto statement", r"\bgoto\s+\w+\s*;", 'goto retry;', 'while ($retry) retry();'),
    r("maint", "multiple-statements-line", "Multiple statements on one line", r";\s+\$[A-Za-z_]\w*\s*=", '$a = 1; $b = 2;', '$a = 1;'),
    r("maint", "suppress-all-errors", "Broad error reporting suppression", r"error_reporting\s*\(\s*0\s*\)", 'error_reporting(0);', 'error_reporting(E_ALL);'),
